def to_int(x):
    try:
        return int(x)
    except Exception:
        return 0

def summarize_sitemaps(sitemaps):
    s=i=0
    for sm in sitemaps or []:
        for c in (sm.get('contents') or []):
            s += to_int(c.get('submitted'))
            i += to_int(c.get('indexed'))
    return {'submitted': s, 'indexed': i}
